import{describe,it,expect,beforeEach}from"vitest";import{initGalleryLightbox,initSmoothScroll}from"../../forest-owlet-explorer/script.js";describe("Forest Owlet Explorer Page (#1319)",()=>{beforeEach(()=>{document.body.innerHTML='\n      <div id="gallery-lightbox" class="lightbox-modal" aria-hidden="true">\n        <span class="lightbox-close">&times;</span>\n        <img id="lightbox-img" src="" alt="">\n        <div id="lightbox-caption"></div>\n      </div>\n      <div class="gallery-item" data-caption="Forest Owlet Test">\n        <img src="test.png" alt="Test Alt">\n        <div class="gallery-caption">Forest Owlet Test</div>\n      </div>\n      <nav class="toc-nav">\n        <a href="#introduction">Introduction</a>\n      </nav>\n      <section id="introduction"></section>\n    '}),it("exports functions correctly",()=>{expect(typeof initGalleryLightbox).toBe("function"),expect(typeof initSmoothScroll).toBe("function")}),it("opens and closes gallery lightbox modal",()=>{initGalleryLightbox();const t=document.getElementById("gallery-lightbox"),e=document.querySelector(".gallery-item"),i=document.querySelector(".lightbox-close");expect(t.getAttribute("aria-hidden")).toBe("true"),e.click(),expect(t.getAttribute("aria-hidden")).toBe("false"),i.click(),expect(t.getAttribute("aria-hidden")).toBe("true")})});